11	/// The chat feature's one remote data source — non-streaming calls go
12	/// through `ApiClient`'s plain JSON methods exactly like
13	/// `EntriesRemoteDataSource`'s own `create`/`list`/`get`; [sendMessage]/
14	/// [retryMessage] alone go through `ApiClient.postStream`, sharing the one
15	/// piece of SSE-specific logic this story introduces (`_consumeSse`):
16	/// splitting the raw byte stream into `event:`/`data:` blocks and mapping
17	/// each into a [ChatStreamEvent] (or an in-band [Failure]) — kept
18	/// feature-local per the Code Map, `ApiClient` itself knows nothing about
19	/// the SSE grammar.
20	class ChatRemoteDataSource {
21	  ChatRemoteDataSource(this._apiClient);
22	
23	  final ApiClient _apiClient;
24	
25	  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
26	    final result = await _apiClient.get('chat-sessions-list');
27	    return result.flatMap((json) {
28	      try {
29	        final data = json['data'] as List<dynamic>;
30	        // Review fix: one malformed item is skipped rather than
31	        // discarding every other valid session in the response — same
32	        // per-item isolation the offline-cache fallback already applies.
33	        final dtos = <ChatSessionDto>[];
34	        for (final item in data) {
35	          try {
36	            dtos.add(ChatSessionDto.fromJson(item as Map<String, dynamic>));
37	          } catch (_) {
38	            // Skip this one malformed item.
39	          }
40	        }
41	        // Review fix: a non-empty response where every item failed to
42	        // decode is a parse failure, not "zero sessions" — returning
43	        // `right([])` here would make `ChatCubit._bootstrap()` believe
44	        // none exist and spuriously `createSession()`, hiding the user's
45	        // real sessions behind a new empty one.
46	        if (data.isNotEmpty && dtos.isEmpty) {
47	          return left(
48	            Failure.malformedResponse(
49	              message: 'All items in listSessions() response failed to decode',
50	            ),
51	          );
52	        }
53	        return right(dtos);
54	      } catch (error) {
55	        // A 200 response that doesn't match the expected shape at all
56	        // (e.g. `data` itself isn't a list) is a client-side parse
57	        // failure, never a backend-sent code — same RNF09 rationale
58	        // `EntriesRemoteDataSource`'s own calls document.
59	        return left(Failure.malformedResponse(message: error.toString()));
60	      }
61	    });
62	  }
63	
64	  /// Sends no `title` (Boundaries: "`chat-sessions-create` with no
65	  /// title") — the contract's own `title` field is optional
66	  /// (`openapi.yaml`), an empty body is valid.
67	  Future<Either<Failure, ChatSessionDto>> createSession() async {
68	    final result = await _apiClient.post('chat-sessions-create', data: const {});
69	    return result.flatMap((json) {
70	      try {
71	        final data = json['data'] as Map<String, dynamic>;
72	        return right(ChatSessionDto.fromJson(data));
73	      } catch (error) {
74	        return left(Failure.malformedResponse(message: error.toString()));
75	      }
76	    });
77	  }
78	
79	  Future<Either<Failure, List<ChatMessageDto>>> listMessages(
80	    String sessionId,
81	  ) async {
82	    final result = await _apiClient.get(
83	      'chat-messages-list',
84	      pathParams: [sessionId],
85	    );
86	    return result.flatMap((json) {
87	      try {
88	        final data = json['data'] as List<dynamic>;
89	        // Review fix: one malformed item is skipped rather than
90	        // discarding every other valid message in the response — same
91	        // per-item isolation the offline-cache fallback already applies.
92	        final dtos = <ChatMessageDto>[];
