29	/// A controllable fake — this suite drives `sendMessage`'s own SSE-shaped
30	/// stream event by event (rather than mocktail-stubbing a fixed `Stream`),
31	/// so each test can assert the cubit's state *between* events (e.g. right
32	/// after one `token` but before `done`).
33	class _FakeChatRepository implements ChatRepository {
34	  Either<Failure, List<ChatSession>> listSessionsResult = right([_session]);
35	  Either<Failure, ChatSession> createSessionResult = right(_session);
36	  Either<Failure, List<ChatMessage>> listMessagesResult = right(const []);
37	
38	  StreamController<Either<Failure, ChatStreamEvent>>? lastSendController;
39	  final List<({String sessionId, String content})> sendMessageCalls = [];
40	
41	  StreamController<Either<Failure, ChatStreamEvent>>? lastRetryController;
42	  final List<({String sessionId, String userMessageId})> retryMessageCalls = [];
43	
44	  @override
45	  Future<Either<Failure, List<ChatSession>>> listSessions() async =>
46	      listSessionsResult;
47	
48	  @override
49	  Future<Either<Failure, ChatSession>> createSession() async =>
50	      createSessionResult;
51	
52	  @override
53	  Future<Either<Failure, List<ChatMessage>>> listMessages(
54	    String sessionId,
55	  ) async => listMessagesResult;
56	
57	  @override
58	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
59	    String sessionId,
60	    String content,
61	  ) {
62	    sendMessageCalls.add((sessionId: sessionId, content: content));
63	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
64	    lastSendController = controller;
65	    return controller.stream;
66	  }
67	
68	  @override
69	  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
70	    String sessionId,
71	    String userMessageId,
72	  ) {
73	    retryMessageCalls.add((sessionId: sessionId, userMessageId: userMessageId));
74	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
75	    lastRetryController = controller;
76	    return controller.stream;
77	  }
78	}
