80	/// spec-6-4 — a controllable fake, same `Completer`-per-call shape
81	/// `pending_entry_write_tracker_test.dart`'s own `_FakeEntriesRepository`
82	/// already uses: lets a test resolve a call whenever it chooses (to
83	/// observe the `saving` state in between), or throw synchronously (I/O
84	/// matrix: "Side-effect throws").
85	class _FakeSaveChatMessageAsEntryUseCase
86	    implements SaveChatMessageAsEntryUseCase {
87	  final List<({String content, String chatMessageId})> calls = [];
88	  final List<Completer<Either<Failure, Entry>>> _completers = [];
89	
90	  /// When set, the *next* [call] throws synchronously instead of
91	  /// recording a completer — exercises `isolatedSideEffect`'s own
92	  /// catch-to-`malformedResponse` path from `bookmarkMessage`'s call site.
93	  bool throwOnNextCall = false;
94	
95	  @override
96	  Future<Either<Failure, Entry>> call({
97	    required String content,
98	    required String chatMessageId,
99	  }) {
100	    calls.add((content: content, chatMessageId: chatMessageId));
101	    if (throwOnNextCall) {
102	      throwOnNextCall = false;
103	      throw Exception('boom');
104	    }
105	    final completer = Completer<Either<Failure, Entry>>();
106	    _completers.add(completer);
107	    return completer.future;
108	  }
109	
110	  void resolve(int callIndex, Either<Failure, Entry> result) {
111	    _completers[callIndex].complete(result);
112	  }
113	}
